	private static final long G1 = id(5);
	private static final long G2 = id(6);

	@Test
	void distinctStatementCompilesWithoutAGenericIsland() {
		LmdbNativeAggregatePlanner planner = planner(new QuadSource());
		SlotPlan plan = planner.compileTuple(new Distinct(statement(false)), false);

		assertThat(plan).isInstanceOf(RowDistinctPlan.class);
		RowDistinctPlan distinct = (RowDistinctPlan) plan;
		assertThat(distinct.arg).isInstanceOf(PatternPlan.class);
		assertThat(distinct.slots).containsExactly(planner.slot("s"), planner.slot("p"), planner.slot("o"));
		assertThat(planner.sawIsland).isFalse();
	}

